// Follow authored motif anchors while untouched; deliberately moved/scaled motifs stay manual.
function followMotifPlacement(previous,next,formats){
 const result=copy(next),base=p=>resolvePoster({...p,formats:{}},'square');
 const placement=o=>motifPlacementForLayout(o.composition.layout,'square',o.composition.density);
 const automatic=(o,f)=>{const a=motifPlacementForLayout(o.composition.layout,f,o.composition.density),m=o.motif;return ['x','y','scale'].every(k=>m[k]===a[k])||(m.id==='none'&&m.x===.75&&m.y===.65&&m.scale===1);};
 const changes=(a,b)=>a.composition.layout!==b.composition.layout||a.composition.density!==b.composition.density||(a.motif.id==='none'&&b.motif.id!=='none');
 const oldBase=base(previous),newBase=base(next);
 if(formats.length===4&&changes(oldBase,newBase)&&automatic(oldBase,'square')){const {x,y,scale}=placement(newBase);result.motif={...result.motif,x,y,scale};}
 for(const f of formats){const a=resolvePoster(previous,f),b=resolvePoster(next,f);if(changes(a,b)&&automatic(a,f)){const {x,y,scale}=motifPlacementForLayout(b.composition.layout,f,b.composition.density);result.formats={...result.formats,[f]:{...result.formats?.[f],motif:{...result.formats?.[f]?.motif,x,y,scale}}};}}
 return normalizePoster(result);
}
