function Button({children,primary=false,icon,...props}){return <button className={'bs-button '+(primary?'bs-primary':'')} {...props}>{icon&&<Icon name={icon}/>} {children}</button>;}
function Field({label,hint,children,className=''}){const id=useId(),items=React.Children.toArray(children);return <label className={'bs-field '+className} htmlFor={id}><span>{label}</span>{React.cloneElement(items[0],{id,'aria-label':label,'aria-describedby':hint?id+'-hint':undefined})}{items.slice(1)}{hint&&<small id={id+'-hint'}>{hint}</small>}</label>;}
function viewportFor(node){let zoom=1;for(let el=node;el;el=el.parentElement){const value=Number.parseFloat(getComputedStyle(el).zoom);if(Number.isFinite(value)&&value>0)zoom*=value;}return {width:(window.visualViewport?.width||window.innerWidth)/zoom,height:(window.visualViewport?.height||window.innerHeight)/zoom,zoom};}
function Modal({title,children,onClose}){const ref=useRef(),titleId=useId();useEffect(()=>{const dialog=ref.current;function fit(){const viewport=viewportFor(dialog);dialog.style.setProperty('--bs-dialog-height',`${Math.max(120,viewport.height-24)}px`);dialog.style.setProperty('--bs-dialog-width',`${Math.max(120,viewport.width-24)}px`);}fit();dialog.showModal();window.addEventListener('resize',fit);window.visualViewport?.addEventListener('resize',fit);const observer=new MutationObserver(fit);observer.observe(document.documentElement,{attributes:true,attributeFilter:['style']});return()=>{window.removeEventListener('resize',fit);window.visualViewport?.removeEventListener('resize',fit);observer.disconnect();dialog.close();};},[]);return <dialog ref={ref} className="bs-modal" aria-labelledby={titleId} onCancel={onClose}><div className="bs-modal-head"><h2 id={titleId}>{title}</h2><button type="button" className="bs-icon" aria-label="Close dialog" onClick={onClose}><Icon name="close"/></button></div>{children}</dialog>;}
const EMPTY={companies:[],campaigns:[],plans:[],posts:[],designs:[],jobs:[],assets:[],settings:{}};
function isoDate(d){return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;}
function weekFor(tz,weekStart=1){let ds;try{ds=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}catch{ds=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}const d=new Date(ds+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()-Number(weekStart)+7)%7);return isoDate(d);}
function shiftWeek(s,n){const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n*7);return isoDate(d);}
function dateLabel(s){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));}
function nice(s){return String(s||'planned').replaceAll('-',' ').replace(/^./,x=>x.toUpperCase());}
